"""session-run 子命令测试：输入校验、全新实例执行、全量查询与确定性输出。"""

import hashlib
import io
import json
import subprocess
import sys
import unittest
from contextlib import contextmanager

import access


def config_v11(cidr="10.0.0.0/29", pools=None, templates=(), user_templates=(),
               template_pools=()):
    if pools is None:
        pools = [
            {"标识": "default", "CIDR": cidr, "保留": [], "静态": []}
        ]
    return {
        "版本": 11,
        "会话": {"总数": 10, "每用户": 5, "空闲毫秒": 1000, "租期毫秒": 5000},
        "地址池": pools,
        "模板": list(templates),
        "用户模板": [list(pair) for pair in user_templates],
        "容量": {"队列上限": 1024, "最大等待毫秒": 0, "队满策略": "拒绝"},
        "认证": {
            "最大失败": 3,
            "锁定毫秒": 1000,
            "重试基数毫秒": 0,
            "重试上限毫秒": 0,
        },
        "模板地址池": [[item[0], list(item[1])] for item in template_pools],
    }


config_v10 = config_v11


def request(key, op, sid, args, now_ms):
    return {"key": key, "op": op, "sid": sid, "args": args, "now_ms": now_ms}


def make_input(requests, users=(("alice", "pw"), ("bob", "pw")),
               config=None, query_ms=0):
    return {
        "users": [list(pair) for pair in users],
        "config": config if config is not None else config_v10(),
        "requests": requests,
        "query_ms": query_ms,
    }


def encode(doc):
    return json.dumps(doc, ensure_ascii=False).encode("utf-8")


def run_raw(raw):
    """直接走 main 分派，返回 (returncode, stdout_bytes, stderr_bytes)。"""
    old_argv, old_stdin, old_stdout, old_stderr = (
        sys.argv, sys.stdin, sys.stdout, sys.stderr
    )
    sys.argv = ["access.py", "session-run"]
    sys.stdin = io.TextIOWrapper(io.BytesIO(raw), encoding="utf-8")
    out = io.TextIOWrapper(io.BytesIO(), encoding="utf-8")
    err = io.TextIOWrapper(io.BytesIO(), encoding="utf-8")
    sys.stdout, sys.stderr = out, err
    try:
        code = access.main(sys.argv)
    finally:
        out.flush()
        err.flush()
        stdout = out.buffer.getvalue()
        stderr = err.buffer.getvalue()
        sys.argv, sys.stdin, sys.stdout, sys.stderr = (
            old_argv, old_stdin, old_stdout, old_stderr
        )
    return code, stdout, stderr


def run_doc(doc):
    return run_raw(encode(doc))


def head_digest(doc):
    head = {key: doc[key] for key in ("版本", "项目", "会话", "地址池")}
    blob = json.dumps(head, ensure_ascii=False, separators=(",", ":"))
    return hashlib.sha256(blob.encode("utf-8")).hexdigest()


class SessionRunSuccessTest(unittest.TestCase):
    def test_basic_run_structure_and_digest(self):
        doc = make_input(
            [
                request("k1", "建立", "s1", ["alice", "pw"], 0),
                request("k2", "建立", "s2", ["bob", "pw"], 0),
                request("k3", "续租", "s1", None, 100),
            ],
            query_ms=200,
        )
        code, stdout, stderr = run_doc(doc)
        self.assertEqual(code, 0)
        self.assertEqual(stderr, b"")
        self.assertTrue(stdout.endswith(b"\n"))
        out = json.loads(stdout)
        self.assertEqual(
            list(out), ["版本", "项目", "会话", "地址池", "摘要"]
        )
        self.assertEqual(out["版本"], 1)
        self.assertEqual([item["序号"] for item in out["项目"]], [0, 1, 2])
        for item in out["项目"]:
            self.assertEqual(
                list(item), ["序号", "结果", "输出", "类型"]
            )
            self.assertTrue(item["结果"])
            self.assertEqual(item["类型"], "")
            self.assertIsNotNone(item["输出"])
        # 建立输出为 do 原返回对象。
        self.assertEqual(out["项目"][0]["输出"]["会话"], "s1")
        self.assertEqual(out["项目"][0]["输出"]["状态"], "在线")

class AuthError(Exception):
    """认证结果非 ok。"""


class ResourceError(Exception):
    """会话总数、单用户会话数或地址池资源已达上限。"""


class StateError(Exception):
    """会话状态不允许当前操作。"""


class BackendError(Exception):
    """后端故障未恢复或退避未到期；值为可重试时刻 retry_at。"""


def _check_int(name, value, minimum):
    """校验非 bool 的 int 且 >= minimum；类型不符 TypeError，越界 ValueError。"""
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"{name} must be an int, got {type(value).__name__}")
    if value < minimum:
        raise ValueError(f"{name} must be >= {minimum}, got {value}")
    return value


def _effective_used(used, last, now_ms, period_ms):
    """按配额周期 P 折算当前有效累计：P>0 且 now_ms 与上次通过时刻 t 不在同一
    周期窗（now_ms//P != t//P）时累计已重置，有效累计为 0；否则为账本 u。
    P=0 表示不重置，恒取 u。调用方须已保证 now_ms >= t。"""
    if period_ms > 0 and now_ms // period_ms != last // period_ms:
        return 0
    return used


def _check_credential(name, value):
    """校验 str、UTF-8 编码后 1..256 字节、不含 U+0000。"""
    if not isinstance(value, str):
        raise TypeError(f"{name} must be a str, got {type(value).__name__}")
    encoded = value.encode("utf-8")
    if not (_MIN_CRED_BYTES <= len(encoded) <= _MAX_CRED_BYTES):
        raise ValueError(
            f"{name} must be 1..256 bytes when UTF-8 encoded, got {len(encoded)}"
        )
    if "\0" in value:
        raise ValueError(f"{name} must not contain U+0000")
    return value


def _check_ip(name, value):
